526:   _updateTowers(dt) {
527:     for (const tower of this.towers) {
528:       tower.cooldown -= dt;
529:       const target = this._findTarget(tower);
530:       if (target) {
531:         const desired = Math.atan2(target.y - (tower.y - 10), target.x - tower.x);
532:         tower.angle = this._turnToward(tower.angle, desired, dt * 9);
533:         if (tower.cooldown <= 0) this._fire(tower, target);
534:       } else {
535:         // Idle scan sweep
536:         tower.angle += Math.sin(this.time * 0.9 + tower.id) * dt * 0.15;
537:       }
538:     }
539:   }
540: 
541:   _turnToward(current, target, maxStep) {
542:     let delta = ((target - current + Math.PI) % TAU) - Math.PI;
543:     if (delta < -Math.PI) delta += TAU;
544:     return current + clamp(delta, -maxStep, maxStep);
545:   }
546: 
547:   _findTarget(tower) {
548:     let best = null;
549:     let bestTravelled = -1;
550:     const r2 = tower.range * tower.range;
551:     for (const e of this.enemies) {
552:       if (e.dead || e.reached) continue;
553:       if (dist2(tower.x, tower.y, e.x, e.y) > r2) continue;
554:       if (e.travelled > bestTravelled) {
555:         bestTravelled = e.travelled;
556:         best = e;
557:       }
558:     }
559:     return best;
560:   }
561: 
562:   _fire(tower, target) {
563:     const def = tower.def;
564:     tower.cooldown = 1 / tower.rate;
565:     tower.recoil = 1;
566:     tower.flash = 1;
567:     const muzzleDist = tower.key === 'sniper' ? 26 : tower.key === 'cannon' ? 20 : 19;
568:     const sx = tower.x + Math.cos(tower.angle) * muzzleDist;
569:     const sy = tower.y - 10 + Math.sin(tower.angle) * muzzleDist;
570: 
571:     if (def.projectile === 'shell') {
572:       // Lead the target a little so the lobbed shell can actually connect.
573:       const travelGuess = Math.hypot(target.x - tower.x, target.y - tower.y) / def.projectileSpeed;
574:       const ahead = Math.min(0.55, travelGuess * 0.65);
575:       const lead = this.pathPointAt(target.travelled + target.speed * ahead);
576:       const dist = Math.hypot(lead.x - sx, lead.y - sy);
577:       this.projectiles.push({
578:         kind: 'shell',
579:         x: sx,
580:         y: sy,
581:         sx,
582:         sy,
583:         tx: lead.x,
584:         ty: lead.y,
585:         t: 0,
586:         duration: Math.max(0.25, dist / def.projectileSpeed),
587:         speed: def.projectileSpeed,
588:         damage: tower.damage,
589:         splash: tower.splash,
590:         pierce: def.pierce,
591:         towerId: tower.id,
592:         towerKey: tower.key,
593:         life: 3,
594:         done: false,
595:       });
596:       this.events.push({ type: 'shoot', kind: 'shell', x: tower.x, y: tower.y, angle: tower.angle, towerId: tower.id });
597:       return;
598:     }
599: 
600:     this.projectiles.push({
601:       kind: def.projectile,
602:       x: sx,
603:       y: sy,
604:       tx: target.x,
605:       ty: target.y,
606:       targetId: target,
607:       speed: def.projectileSpeed,
608:       damage: tower.damage,
609:       pierce: def.pierce,
610:       splash: 0,
611:       slow: def.slow || 0,
612:       slowDuration: def.slowDuration || 0,
613:       towerId: tower.id,
614:       towerKey: tower.key,
615:       color: def.color,
616:       life: 2.2,
617:       trail: [],
618:       done: false,
619:     });
620:     this.events.push({ type: 'shoot', kind: def.projectile, x: tower.x, y: tower.y, angle: tower.angle, towerId: tower.id });
621:   }
622: 
623:   _updateProjectiles(dt) {
624:     for (const p of this.projectiles) {
625:       if (p.done) continue;
626:       if (p.kind === 'shell') {
627:         p.t += dt / p.duration;
628:         if (p.t >= 1) {
629:           this._explodeShell(p);
630:           continue;
631:         }
632:         const t = p.t;
633:         p.x = lerp(p.sx, p.tx, t);
634:         p.y = lerp(p.sy, p.ty, t) - Math.sin(t * Math.PI) * Math.min(90, Math.hypot(p.tx - p.sx, p.ty - p.sy) * 0.35);
635:         continue;
636:       }
637: 
638:       if (p.targetId && !p.targetId.dead && !p.targetId.reached) {
639:         p.tx = p.targetId.x;
640:         p.ty = p.targetId.y;
641:       } else {
642:         p.targetId = null;
643:       }
644: 
645:       const dx = p.tx - p.x;
646:       const dy = p.ty - p.y;
647:       const d = Math.hypot(dx, dy);
648:       const step = p.speed * dt;
649:       if (d <= step + 8) {
650:         // Hit
651:         p.x = p.tx;
652:         p.y = p.ty;
653:         if (p.targetId) this._hitProjectile(p, p.targetId);
654:         p.done = true;
655:         continue;
656:       }
657:       p.x += (dx / d) * step;
658:       p.y += (dy / d) * step;
659:       p.life -= dt;
660:       if (p.life <= 0) {
661:         p.done = true;
662:         continue;
663:       }
664:       p.trail.push({ x: p.x, y: p.y });
665:       if (p.trail.length > 6) p.trail.shift();
666:     }
667:   }
668: 
669:   _hitProjectile(p, target) {
670:     if (p.kind === 'ice') {
671:       this._damageEnemy(target, p.damage, { pierce: p.pierce, towerId: p.towerId });
672:       if (!target.dead) this._applySlow(target, p.slow, p.slowDuration);
673:       this.events.push({ type: 'impact', kind: 'ice', x: p.x, y: p.y });
674:       return;
675:     }
676:     const dealt = this._damageEnemy(target, p.damage, { pierce: p.pierce, towerId: p.towerId });
677:     if (p.kind === 'tracer') this.events.push({ type: 'impact', kind: 'tracer', x: p.x, y: p.y, dealt });
678:     else this.events.push({ type: 'impact', kind: 'bullet', x: p.x, y: p.y, dealt });
679:   }
680: 
681:   _explodeShell(p) {
682:     p.done = true;
683:     p.x = p.tx;
684:     p.y = p.ty;
685:     this.events.push({ type: 'explosion', x: p.tx, y: p.ty, radius: p.splash });
686:     const r2 = p.splash * p.splash;
687:     for (const e of this.enemies) {
688:       if (e.dead || e.reached) continue;
689:       const d2 = dist2(p.tx, p.ty, e.x, e.y);
690:       if (d2 <= r2 + e.radius * e.radius) {
691:         const falloff = clamp(1.15 - Math.sqrt(d2) / (p.splash + 20), 0.45, 1);
692:         this._damageEnemy(e, p.damage * falloff, { pierce: p.pierce, splash: true, towerId: p.towerId });
693:       }
694:     }
695:   }
696: 
697:   _applySlow(enemy, slow, duration) {
698:     const resist = enemy.def.slowResist || 0;
699:     const factor = 1 - slow * (1 - resist);
700:     if (enemy.slowFactor > factor || this.time >= enemy.slowUntil) enemy.slowFactor = factor;
701:     enemy.slowUntil = Math.max(enemy.slowUntil, this.time + duration);
702:     this.events.push({ type: 'slow', x: enemy.x, y: enemy.y });
703:   }
704: 
705:   _damageEnemy(enemy, raw, { pierce = 0, splash = false, towerId = 0 } = {}) {
706:     if (!enemy || enemy.dead) return 0;
707:     let armor = enemy.armor * (1 - pierce);
708:     if (splash) armor *= 0.6;
709:     const dmg = Math.max(1, raw - armor);
710:     enemy.hp -= dmg;
711:     enemy.hitFlash = 1;
712:     const tower = this.towers.find((t) => t.id === towerId);
713:     if (tower) {
714:       tower.damageDone += dmg;
715:       if (enemy.hp <= 0) tower.kills++;
716:     }
717:     if (enemy.hp <= 0) {
718:       enemy.hp = 0;
719:       enemy.dead = true;
720:       this.coins += enemy.reward;
721:       this.totalEarned += enemy.reward;
722:       this.totalKills++;
723:       this.waveKills++;
724:       this.events.push({
725:         type: 'kill',
726:         x: enemy.x,
727:         y: enemy.y,
728:         enemy: enemy.key,
729:         reward: enemy.reward,
730:         boss: enemy.key === 'boss',
731:       });
732:     }
733:     return dmg;
734:   }
735: 
736:   // -------------------------------------------------------------------------
737:   // Read-only helpers for UI / renderer
738:   // -------------------------------------------------------------------------
739:   get timeToNextWave() {
740:     return this.phase === 'prep' ? Math.max(0, Math.ceil(this.phaseTimer)) : null;
741:   }
742: 
743:   get waveProgress() {
744:     return { wave: Math.max(1, this.wave), max: CONFIG.maxWaves };
745:   }
746: 
747:   get selectedTower() {
748:     return this.selectedTowerId ? this.getTower(this.selectedTowerId) : null;
749:   }
750: 
751:   get upgradeCost() {
752:     const t = this.selectedTower;
753:     return t ? t.upgradeCost : null;
754:   }
755: 
756:   drainEvents() {
757:     const out = this.events;
758:     this.events = [];
759:     return out;
760:   }
761: }

