  ctx.fillStyle = def.color; ctx.beginPath(); ctx.arc(0, -2, 13, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = def.light; ctx.lineWidth = 1.3; ctx.beginPath(); ctx.arc(0, -2, 10, .2, 2.8); ctx.stroke();
