46:     if (game.wave !== lastWave) {
47:       if (lastWave) waveLog.push({ wave: lastWave, hp: game.baseHp, towers: game.towers.length, coins: game.coins });
48:       lastWave = game.wave;
49:     }
50:     if (game.baseHp !== lastHp) lastHp = game.baseHp;
51: 
52:     decide += DT;
53:     if (decide < 0.35) continue;
54:     decide = 0;
55: 
56:     if (game.phase === 'prep' || game.phase === 'spawning' || game.phase === 'clearing') {
57:       // Build planned towers first, then upgrade.
58:       while (orderIndex < buildOrder.length) {
