201: function drawTerrain(w, h) {
202:   ctx.save();
203:   const top = game.fieldTop, bottom = game.fieldBottom;
204:   ctx.fillStyle = 'rgba(25,41,38,.22)'; ctx.fillRect(0, top, w, bottom - top);
205:   // soft terrain bands
206:   for (let i = 0; i < 7; i++) {
207:     ctx.beginPath();
208:     const y = top + (bottom - top) * (i + .5) / 7;
209:     ctx.ellipse(w * ((i % 2) ? .22 : .78), y, w * .48, 36 + i * 3, 0, 0, Math.PI * 2);
210:     ctx.fillStyle = i % 2 ? 'rgba(138,162,112,.055)' : 'rgba(10,25,28,.07)'; ctx.fill();
211:   }
212:   // small scrub and stones in deterministic scatter
213:   for (let i = 0; i < 42; i++) {
214:     const x = ((i * 97 + 31) % 997) / 997 * w;
215:     const y = top + ((i * 163 + 71) % 991) / 991 * (bottom - top);
216:     if (game._pathDistance(x, y) < game.laneHalf + 18) continue;
217:     const r = 2 + (i % 4) * .8;
218:     if (i % 3 === 0) {
219:       ctx.fillStyle = '#172d2c66'; ctx.beginPath(); ctx.ellipse(x, y + 3, r * 2, r * .8, .2, 0, 7); ctx.fill();
220:       ctx.fillStyle = i % 2 ? '#82936a' : '#9a9866'; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
221:     } else {
222:       ctx.fillStyle = i % 2 ? '#b0a27744' : '#b5c1b33c'; ctx.beginPath(); ctx.ellipse(x, y, r * 1.3, r * .7, .3, 0, 7); ctx.fill();
223:     }
224:   }
225:   ctx.restore();
226: }
