232: function drawPath() {
233:   ctx.save(); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
234:   tracePath(); ctx.strokeStyle = '#101a23a8'; ctx.lineWidth = CONFIG.laneWidth + 13; ctx.stroke();
235:   tracePath(); ctx.strokeStyle = '#665b49'; ctx.lineWidth = CONFIG.laneWidth + 1; ctx.stroke();
236:   tracePath(); ctx.strokeStyle = '#a08a69'; ctx.lineWidth = CONFIG.laneWidth - 8; ctx.stroke();
237:   tracePath(); ctx.strokeStyle = '#b6a17d'; ctx.lineWidth = CONFIG.laneWidth - 19; ctx.stroke();
238:   tracePath(); ctx.setLineDash([3, 12]); ctx.strokeStyle = '#e3ce9c62'; ctx.lineWidth = 2; ctx.stroke(); ctx.setLineDash([]);
239:   // scattered road marks
240:   for (let d = 35; d < game.pathLength; d += 57) {
241:     const p = game.pathPointAt(d);
242:     ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.angle);
243:     ctx.fillStyle = '#6e624d4d'; ctx.fillRect(-6, -12, 13, 3); ctx.restore();
244:   }
245:   ctx.restore();
