288:   ctx.fillStyle = def.dark; ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI * 2); ctx.fill();
289:   ctx.fillStyle = def.color; ctx.beginPath(); ctx.arc(0, -2, 13, 0, Math.PI * 2); ctx.fill();
290:   ctx.strokeStyle = def.light; ctx.lineWidth = 1.3; ctx.beginPath(); ctx.arc(0, -2, 10, .2, 2.8); ctx.stroke();
291:   if (t.key === 'machine') {
292:     ctx.save(); ctx.rotate(t.angle); ctx.fillStyle = '#d7e4c4'; roundRect(0, -7, 18, 5, 2); ctx.fill(); ctx.fillStyle = '#536c50'; roundRect(7, -8, 13, 3, 1); ctx.fill(); ctx.restore();
293:     ctx.fillStyle = '#f2ffe1'; ctx.beginPath(); ctx.arc(-2, -3, 3.3, 0, 7); ctx.fill();
294:   } else if (t.key === 'sniper') {
295:     ctx.save(); ctx.rotate(t.angle); ctx.fillStyle = '#d4e7ec'; roundRect(-1, -3, 25, 4, 2); ctx.fill(); ctx.fillStyle = '#78c6f4'; roundRect(4, -5, 8, 3, 1); ctx.fill(); ctx.restore();
296:     ctx.fillStyle = '#e5f6ff'; ctx.beginPath(); ctx.arc(-2, -3, 3, 0, 7); ctx.fill();
297:   } else if (t.key === 'cannon') {
298:     ctx.save(); ctx.rotate(t.angle); ctx.fillStyle = '#e4b979'; roundRect(-2, -7, 23, 14, 4); ctx.fill(); ctx.fillStyle = '#533c2a'; ctx.beginPath(); ctx.arc(18, 0, 4.5, 0, 7); ctx.fill(); ctx.restore();
299:     ctx.fillStyle = '#ffe0a2'; ctx.beginPath(); ctx.arc(-3, -3, 3.2, 0, 7); ctx.fill();
300:   } else {
301:     ctx.save(); ctx.rotate(t.spin); ctx.strokeStyle = '#e2ffff'; ctx.lineWidth = 2.2;
302:     for (let i = 0; i < 4; i++) { ctx.rotate(Math.PI / 2); ctx.beginPath(); ctx.moveTo(0, -4); ctx.lineTo(0, -15); ctx.stroke(); ctx.beginPath(); ctx.arc(0, -15, 2.5, 0, 7); ctx.fillStyle = '#c9ffff'; ctx.fill(); }
303:     ctx.restore(); ctx.fillStyle = '#e7ffff'; ctx.beginPath(); ctx.arc(0, -2, 4, 0, 7); ctx.fill();
304:   }
305:   if (t.flash > .3) { ctx.globalAlpha = t.flash * .8; ctx.fillStyle = '#fff1bb'; ctx.beginPath(); ctx.arc(Math.cos(t.angle) * 17, -2 + Math.sin(t.angle) * 17, 5 + t.flash * 4, 0, 7); ctx.fill(); }
306:   ctx.fillStyle = '#152332'; roundRect(-10, 12, 20, 10, 3); ctx.fill();
307:   ctx.fillStyle = def.light; ctx.font = '800 8px "DM Sans"'; ctx.textAlign = 'center'; ctx.fillText(String(t.level), 0, 20);
308:   if (selected) { ctx.strokeStyle = '#fff1b7'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(0, -2, 18, 0, 7); ctx.stroke(); }
