312: function drawEnemy(e) {
313:   const def = e.def;
314:   const r = e.radius;
315:   const bob = Math.sin(e.wobble * 7 + e.bob) * 1.5;
316:   ctx.save(); ctx.translate(e.x, e.y + bob); ctx.rotate(e.angle);
317:   ctx.fillStyle = '#07121b66'; ctx.beginPath(); ctx.ellipse(0, r * .8, r * 1.05, r * .48, 0, 0, 7); ctx.fill();
318:   if (e.key === 'boss') {
319:     ctx.fillStyle = '#451827'; ctx.beginPath(); ctx.moveTo(-r * .7, -r * .5); ctx.lineTo(-r * .55, -r * 1.2); ctx.lineTo(-r * .15, -r * .82); ctx.lineTo(r * .2, -r * 1.3); ctx.lineTo(r * .65, -r * .45); ctx.closePath(); ctx.fill();
320:   }
321:   ctx.fillStyle = e.hitFlash ? '#fff' : def.dark;
322:   ctx.beginPath(); ctx.ellipse(0, 0, r * 1.03, r * .83, 0, 0, 7); ctx.fill();
323:   ctx.fillStyle = e.hitFlash ? '#fff' : def.color;
324:   ctx.beginPath(); ctx.ellipse(0, -1, r * .79, r * .68, 0, 0, 7); ctx.fill();
325:   ctx.fillStyle = def.light; ctx.beginPath(); ctx.ellipse(r * .22, -r * .1, r * .38, r * .22, -.2, 0, 7); ctx.fill();
326:   // facing eye and small directional spikes
327:   ctx.fillStyle = '#17202a'; ctx.beginPath(); ctx.arc(r * .45, -r * .2, Math.max(1.5, r * .12), 0, 7); ctx.fill();
328:   if (e.key === 'fast') { ctx.fillStyle = '#ffe6a1'; ctx.beginPath(); ctx.moveTo(-r * .2, -r * .7); ctx.lineTo(-r * .85, -r * 1.05); ctx.lineTo(-r * .55, -.15); ctx.fill(); }
329:   if (e.key === 'armored' || e.key === 'boss') {
330:     ctx.fillStyle = '#d1d0dd'; ctx.strokeStyle = '#66647c'; ctx.lineWidth = 1;
331:     ctx.beginPath(); ctx.ellipse(-r * .08, -r * .15, r * .63, r * .48, -.12, Math.PI, Math.PI * 2); ctx.fill(); ctx.stroke();
332:     ctx.beginPath(); ctx.moveTo(-r * .55, -r * .15); ctx.lineTo(r * .5, -r * .15); ctx.stroke();
333:   }
334:   ctx.restore();
335:   // health bar
336:   const barW = e.key === 'boss' ? 42 : r * 2.25;
337:   const barY = e.y - r - 9;
338:   ctx.fillStyle = '#111b25d9'; roundRect(e.x - barW / 2, barY, barW, 4, 2); ctx.fill();
339:   ctx.fillStyle = e.hp / e.maxHp < .3 ? '#ff6570' : '#80e7a4'; roundRect(e.x - barW / 2, barY, barW * Math.max(0, e.hp / e.maxHp), 4, 2); ctx.fill();
340:   if (e.slowed) { ctx.strokeStyle = '#9bffffaa'; ctx.lineWidth = 1.3; ctx.beginPath(); ctx.arc(e.x, e.y, r + 4, 0, 7); ctx.stroke(); }
341: }
