381: function frame(now) {
382:   requestAnimationFrame(frame);
383:   const realDt = Math.min(.05, Math.max(0, (now - lastTime) / 1000));
384:   lastTime = now;
385:   if (!paused && game.status === 'running') {
386:     const dt = realDt * speeds[speedIndex];
387:     game.update(dt);
388:     processEvents();
389:     for (const p of particles) { p.x += p.vx * realDt; p.y += p.vy * realDt; p.vx *= .94; p.vy *= .94; p.life -= realDt; }
390:     for (const f of floating) { f.y -= realDt * 23; f.life -= realDt; }
391:     for (let i = particles.length - 1; i >= 0; i--) if (particles[i].life <= 0) particles.splice(i, 1);
