39:     const r = Math.min(radius, d1 * 0.42, d2 * 0.42);
40:     const a = { x: p1.x + ((p0.x - p1.x) / (d1 || 1)) * r, y: p1.y + ((p0.y - p1.y) / (d1 || 1)) * r };
41:     const b = { x: p1.x + ((p2.x - p1.x) / (d2 || 1)) * r, y: p1.y + ((p2.y - p1.y) / (d2 || 1)) * r };
42:     out.push(a);
