51: 
52:     decide += DT;
53:     if (decide < 0.35) continue;
54:     decide = 0;
55: 
56:     if (game.phase === 'prep' || game.phase === 'spawning' || game.phase === 'clearing') {
57:       // Build planned towers first, then upgrade.
58:       while (orderIndex < buildOrder.length) {
59:         const key = buildOrder[orderIndex];
60:         if (game.coins < TOWERS[key].cost) break;
61:         const slot = bestSlot(game, key);
62:         if (!slot) {
63:           orderIndex++;
64:           continue;
65:         }
66:         const r = game.buildTower(key, slot.x, slot.y);
67:         if (r.ok) orderIndex++;
68:         else break;
69:       }
70:       if (game.towers.length >= upgradeBefore || orderIndex >= buildOrder.length) {
71:         // Upgrade the cheapest available option, favoring low levels.
72:         const options = game.towers
73:           .filter((tw) => !tw.maxed && game.coins >= tw.upgradeCost)
74:           .sort((a, b) => a.upgradeCost - b.upgradeCost);
75:         if (options.length) game.upgradeTower(options[0].id);
76:       }
77:     }
78:   }
79: 
80:   waveLog.push({ wave: game.wave, hp: game.baseHp, towers: game.towers.length, coins: game.coins, kills: game.totalKills });
81:   return { name, status: game.status, wave: game.wave, hp: game.baseHp, towers: game.towers.length, kills: game.totalKills, log: waveLog, time: t, orderUsed: orderIndex };
82: }
